insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-1', 'اختبار مقدمة في التسويق', 70, '[{"q":"التسويق بشكل أساسي هو:","options":["بيع المنتج بأي وسيلة ممكنة","خلق قيمة حقيقية وإيصالها للعميل المناسب","الإعلان فقط","تخفيض الأسعار باستمرار"],"correctIndex":1},{"q":"الفرق الأساسي بين البيع والتسويق:","options":["لا يوجد فرق بينهما","البيع يركز على الصفقة الفورية، والتسويق يبني علاقة وقيمة طويلة المدى","التسويق أرخص من البيع دائمًا","البيع يسبق التسويق دائمًا"],"correctIndex":1},{"q":"من أهم عناصر التسويق الأساسية:","options":["المنتج، السعر، الترويج، التوزيع","الشعار فقط","عدد الموظفين","رأس المال فقط"],"correctIndex":0},{"q":"أحد أكبر تأثيرات ظهور التسويق الرقمي:","options":["اختفاء الحاجة للتسويق التقليدي كليًا","طريقة أدق للوصول للعملاء وقياس النتائج","أصبح بناء العلامة التجارية غير مهم","لم يتغيّر شيء"],"correctIndex":1},{"q":"أي مما يلي مفهوم خاطئ شائع عن التسويق؟","options":["التسويق هو الإعلان فقط","التسويق عملية مستمرة تشمل البحث والتخطيط","التسويق يبدأ بفهم العميل","التسويق مرتبط بخلق قيمة"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch2', 'رحلة العميل (Customer Journey)', 2) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-2', 'اختبار رحلة العميل (Customer Journey)', 70, '[{"q":"ما هي أول مرحلة في رحلة العميل / قمع المبيعات؟","options":["الشراء","الوعي (Awareness)","الولاء","الاحتفاظ بالعميل"],"correctIndex":1},{"q":"مرحلة \"الاحتفاظ بالعميل\" (Retention) تأتي:","options":["قبل الشراء","بعد الشراء","بدلاً من الوعي","لا علاقة لها بالرحلة"],"correctIndex":1},{"q":"\"المدافعة / التأييد\" (Advocacy) تعني:","options":["العميل يشتري لأول مرة","العميل يوصي بالمنتج للآخرين","العميل يتردد في الشراء","العميل يطلب استرجاع المنتج"],"correctIndex":1},{"q":"مرحلة \"النية\" (Intent) تسبق مباشرة مرحلة:","options":["الوعي","الشراء","الولاء","الاهتمام"],"correctIndex":1},{"q":"فهم رحلة العميل الكاملة يساعد المسوّق على:","options":["تجاهل احتياجات العميل","فهم وتوجيه العميل في كل مرحلة نحو القرار","تقليل جودة المنتج","رفع الأسعار فقط"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch3', 'فهم العميل (Customer Understanding)', 3) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-3', 'اختبار فهم العميل (Customer Understanding)', 70, '[{"q":"\"شخصية العميل\" (Buyer Persona) هي:","options":["صورة تمثيلية للعميل المثالي مبنية على بيانات حقيقية","اسم المنتج","شعار الشركة","قائمة أسعار"],"correctIndex":0},{"q":"\"نقاط الألم\" (Pain Points) تشير إلى:","options":["مميزات المنتج","المشكلات والتحديات التي يواجهها العميل","أرباح الشركة","عدد الموظفين"],"correctIndex":1},{"q":"العميل في الأساس يشتري:","options":["المنتج نفسه فقط","النتيجة أو الفائدة التي يحصل عليها","اسم الشركة","لون التغليف فقط"],"correctIndex":1},{"q":"فهم \"مخاوف\" العميل يساعد المسوّق على:","options":["تجاهلها","معالجتها وطمأنة العميل قبل الشراء","زيادة السعر دون سبب","قطع التواصل معه"],"correctIndex":1},{"q":"الدوافع النفسية للشراء غالبًا ما تكون:","options":["منطقية بحتة فقط","مزيجًا من العاطفة والمنطق","عشوائية تمامًا","غير قابلة للدراسة"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into lessons (course_id, lesson_key, title, position) values ((select id from courses where slug='marketing-launch'), 'ch4', 'علم النفس التسويقي (Marketing Psychology)', 4) on conflict (course_id, lesson_key) do update set title=excluded.title, position=excluded.position;
insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-4', 'اختبار علم النفس التسويقي (Marketing Psychology)', 70, '[{"q":"\"التسويق العاطفي\" يعتمد بشكل أساسي على:","options":["الأرقام والإحصائيات فقط","إثارة مشاعر العميل لدفعه لاتخاذ القرار","خفض الأسعار فقط","المواصفات التقنية فقط"],"correctIndex":1},{"q":"\"الانحيازات الإدراكية\" (Cognitive Biases) هي:","options":["أخطاء عشوائية بلا نمط","أنماط تفكير متكررة تؤثر على قرارات الشراء","قوانين تسويقية رسمية","نوع من الإعلانات المدفوعة"],"correctIndex":1},{"q":"الألوان في التسويق:","options":["لا تأثير لها إطلاقًا","تؤثر على المشاعر والانطباعات المرتبطة بالعلامة التجارية","تُستخدم فقط للزينة","لها نفس المعنى في كل الثقافات دائمًا"],"correctIndex":1},{"q":"غالبية قرارات الشراء تُتخذ عبر:","options":["منطق بحت 100%","تأثير عاطفي أولاً يليه تبرير منطقي","عشوائية كاملة","لا علاقة للعاطفة بها إطلاقًا"],"correctIndex":1},{"q":"\"التسويق العصبي\" (Neuromarketing) يدرس:","options":["استجابة الدماغ والجهاز العصبي للمؤثرات التسويقية","الميزانية الإعلانية فقط","عدد المنافسين","توزيع الفروع"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
