insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-5', 'اختبار مبادئ التسويق', 70, '[{"q":"المزيج التسويقي (Marketing Mix) الأساسي 4Ps يتكوّن من:","options":["Product, Price, Place, Promotion","People, Process, Physical, Product","Plan, Price, Post, Promo","Product, Profit, Place, People"],"correctIndex":0},{"q":"عند الحديث عن الخدمات، يُضاف إلى 4Ps ثلاثة عناصر لتصبح 7Ps، من بينها:","options":["People (الأفراد)","Politics (السياسة)","Population (السكان)","Print (الطباعة)"],"correctIndex":0},{"q":"نموذج STP يبدأ بمرحلة:","options":["Segmentation (تقسيم السوق)","Sales (المبيعات)","Strategy (الاستراتيجية العامة)","Support (الدعم)"],"correctIndex":0},{"q":"في نموذج AIDA، الحرف A الأول يشير إلى:","options":["Advocacy (التأييد)","Attention (الانتباه)","Action (الإجراء)","Awareness فقط بلا انتباه"],"correctIndex":1},{"q":"\"USP\" (الميزة البيعية الفريدة) تجيب على سؤال:","options":["كم سعر المنتج؟","لماذا يشتري العميل منك أنت تحديدًا وليس من المنافسين؟","أين يباع المنتج؟","من هو المدير التنفيذي للشركة؟"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
