insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-6', 'اختبار أنواع التسويق (Marketing Types)', 70, '[{"q":"التسويق عبر المؤثرين (Influencer Marketing) يعتمد على:","options":["استخدام أشخاص ذوي تأثير ومتابعين للترويج للمنتج","الإعلانات التلفزيونية فقط","خفض السعر فقط","توزيع منشورات ورقية"],"correctIndex":0},{"q":"التسويق الفيروسي (Viral Marketing) يهدف إلى:","options":["انتشار المحتوى بسرعة كبيرة عبر المشاركة بين الناس","بيع منتج واحد فقط","تقليل عدد المتابعين","إيقاف الحملات الإعلانية"],"correctIndex":0},{"q":"التسويق عبر محركات البحث (SEM/SEO) يركّز على:","options":["الظهور أمام العملاء عند بحثهم عن كلمات متعلقة بمنتجك","توزيع كروت ورقية","الإعلانات في الراديو فقط","لا علاقة له بالإنترنت"],"correctIndex":0},{"q":"إعادة الاستهداف (Retargeting) تعني:","options":["استهداف عملاء جدد تمامًا فقط","إعادة عرض إعلانات لأشخاص تفاعلوا مع المنتج سابقًا ولم يشتروا","حذف بيانات العملاء","إلغاء الحملة الإعلانية"],"correctIndex":1},{"q":"عند اختيار نوع التسويق المناسب لنشاطك التجاري، يجب مراعاة:","options":["طبيعة الجمهور المستهدف والميزانية والأهداف","اختيار كل الأنواع دفعة واحدة دون تخطيط","تقليد المنافس دون تحليل","تجاهل الجمهور المستهدف"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
