insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-7', 'اختبار أساسيات العلامة التجارية', 70, '[{"q":"العلامة التجارية (Brand) هي بشكل أساسي:","options":["الشعار فقط","الصورة والانطباع والمشاعر التي تتكون في ذهن العميل","اسم المنتج فقط","لون العبوة فقط"],"correctIndex":1},{"q":"\"الهوية البصرية\" (Visual Identity) تشمل:","options":["الألوان والخطوط والشعار وعناصر التصميم","الأرباح السنوية فقط","عدد الفروع","سياسة الاسترجاع فقط"],"correctIndex":0},{"q":"\"نبرة التواصل\" (Tone of Voice) تعني:","options":["حجم صوت الإعلان التلفزيوني","طريقة وأسلوب حديث العلامة التجارية مع جمهورها","سرعة تحميل الموقع","لون الخط المستخدم فقط"],"correctIndex":1},{"q":"\"التموضع\" (Positioning) هو:","options":["المكانة التي تحتلها العلامة التجارية في ذهن العميل مقارنة بالمنافسين","موقع المتجر الجغرافي فقط","عدد المنتجات المعروضة","سعر المنتج الأساسي"],"correctIndex":0},{"q":"\"وعد العلامة التجارية\" (Brand Promise) هو:","options":["إعلان مؤقت لتخفيضات الموسم","التعهد الذي تقدمه العلامة لعملائها في كل تعامل","اسم المنتج الجديد","عدد الموظفين في الفريق"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
