insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-8', 'اختبار أساسيات كتابة المحتوى (Content Writing Basics)', 70, '[{"q":"الهدف الأساسي من كتابة المحتوى التسويقي هو:","options":["ملء المساحة فقط دون هدف","تقديم قيمة للجمهور وبناء الثقة وتحقيق هدف تسويقي محدد","استخدام أطول الجمل الممكنة","تجنّب أي عاطفة في الكتابة"],"correctIndex":1},{"q":"نموذج AIDA في كتابة الإعلانات يبدأ بـ:","options":["Attention (جذب الانتباه)","Action (طلب إجراء) مباشرة","Advocacy (التأييد)","Analysis (التحليل)"],"correctIndex":0},{"q":"\"CTA\" في المحتوى التسويقي تعني:","options":["نوعًا من الخطوط","دعوة واضحة لاتخاذ إجراء (Call To Action)","اسم برنامج تصميم","نوعًا من الألوان"],"correctIndex":1},{"q":"\"Storytelling\" (سرد القصص) في المحتوى يساعد على:","options":["تعقيد الرسالة التسويقية بلا داعٍ","خلق ارتباط عاطفي مع الجمهور يجعل الرسالة أكثر تأثيرًا","إخفاء مميزات المنتج","تقليل مصداقية العلامة التجارية"],"correctIndex":1},{"q":"من الأخطاء الشائعة في كتابة المحتوى:","options":["التركيز على احتياج الجمهور","الكتابة بلا هدف واضح أو دعوة لاتخاذ إجراء","استخدام لغة واضحة","مراعاة نبرة العلامة التجارية"],"correctIndex":1}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
