insert into quizzes (course_id, quiz_key, title, passing_score, questions) values ((select id from courses where slug='marketing-launch'), 'quiz-9', 'اختبار مقدمة في التسويق الرقمي (Digital Marketing Fundamentals)', 70, '[{"q":"التسويق الرقمي يشمل بشكل أساسي:","options":["الترويج للمنتجات والخدمات عبر القنوات والمنصات الإلكترونية","الإعلانات المطبوعة فقط","التوزيع عبر المتاجر التقليدية فقط","المكالمات الهاتفية العشوائية فقط"],"correctIndex":0},{"q":"من أهم المنصات الرقمية التي يعمل عليها المسوّق الرقمي:","options":["منصات التواصل الاجتماعي ومحركات البحث والبريد الإلكتروني","المطابع الورقية فقط","اللوحات الإعلانية الثابتة فقط","لا توجد منصات محددة"],"correctIndex":0},{"q":"مسار العميل الرقمي (Digital Customer Path) يساعد المسوّق على:","options":["فهم خطوات العميل الإلكترونية من أول ظهور الإعلان حتى الشراء","تجاهل سلوك العميل على الإنترنت","زيادة السعر تلقائيًا","حذف بيانات العملاء"],"correctIndex":0},{"q":"من مميزات التسويق الرقمي مقارنة بالتقليدي:","options":["إمكانية القياس الدقيق للنتائج واستهداف جمهور محدد","استحالة قياس أي نتيجة","تكلفة أعلى دائمًا بلا استثناء","عدم إمكانية الاستهداف نهائيًا"],"correctIndex":0},{"q":"أنواع الإعلانات الرقمية تشمل غالبًا:","options":["إعلانات البحث والعرض والفيديو والسوشيال ميديا","الإعلانات الإذاعية فقط","المنشورات الورقية فقط","لا يوجد أنواع مختلفة"],"correctIndex":0}]'::jsonb) on conflict (course_id, quiz_key) do update set title=excluded.title, passing_score=excluded.passing_score, questions=excluded.questions;
insert into projects (course_id, project_key, title, instructions, passing_score) values ((select id from courses where slug='marketing-launch'), 'graduation-project', 'مشروع التخرج — Marketing Launch', 'أنشئ خطة إطلاق تسويقية متكاملة لمنتج أو خدمة حقيقية أو افتراضية. وضّح العميل المثالي، القيمة المقترحة، الهوية، القنوات، المحتوى، الإعلانات، الميزانية، مؤشرات القياس، ورحلة العميل.', 70) on conflict (course_id, project_key) do update set title=excluded.title, instructions=excluded.instructions, passing_score=excluded.passing_score;
